// Recibe parámetros del agente y construye la query string para la API de Lauka
const input = $input.first().json;

const BASE = 'https://194.195.92.107:444/rest/default/V1/lauka/products';

const parts = [];

// Paginación
const pagina = parseInt(input.pagina) || 1;
const pageSize = parseInt(input.page_size) || 10;
parts.push(`searchCriteria[currentPage]=${pagina}`);
parts.push(`searchCriteria[pageSize]=${pageSize}`);

// Ordenamiento
const ordenar = (input.ordenar_por || '').trim().toLowerCase();
if (ordenar === 'bestsellers') {
  parts.push('sort=bestsellers');
} else if (ordenar === 'precio_asc') {
  parts.push('searchCriteria[sortOrders][0][field]=sale_price');
  parts.push('searchCriteria[sortOrders][0][direction]=ASC');
} else if (ordenar === 'precio_desc') {
  parts.push('searchCriteria[sortOrders][0][field]=sale_price');
  parts.push('searchCriteria[sortOrders][0][direction]=DESC');
} else if (ordenar === 'nombre') {
  parts.push('searchCriteria[sortOrders][0][field]=name');
  parts.push('searchCriteria[sortOrders][0][direction]=ASC');
}

// Filtros dinámicos — grupos separados = AND entre ellos
let groupIdx = 0;

// ── Búsqueda por término (OR sobre campos confiables, EXCLUYE sku/skux) ──────
// Reemplazamos q= porque ese parámetro incluye sku/skux que contienen texto
// descriptivo sucio (ej: el sku puede decir "El Termómetro LAUKA se utiliza...")
// lo que causa falsos positivos. Con filterGroups controlamos exactamente qué
// campos se buscan.
const q = (input.termino_busqueda || '').trim();
if (q) {
  const val = encodeURIComponent('%' + q + '%');
  const camposBusqueda = [
    'name',
    'short_description',
    'description',
    'tags',
    'brand',
    'grupo',
    'subcategoria',
    'categories',
    'gtin',
    'fabricante',
    'material',
    'tipo_capacidad',
    'caracteristica_1',
    'caracteristica_2',
    'medida'
  ];
  camposBusqueda.forEach((campo, filterIdx) => {
    parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][${filterIdx}][field]=${campo}`);
    parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][${filterIdx}][value]=${val}`);
    parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][${filterIdx}][condition_type]=like`);
  });
  groupIdx++;
}

// Marca (eq) — grupo separado = AND con la búsqueda
const marca = (input.marca || '').trim();
if (marca) {
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][field]=brand`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][value]=${encodeURIComponent(marca)}`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][condition_type]=eq`);
  groupIdx++;
}

// Categoría / subcategoría (like)
const categoria = (input.categoria || '').trim();
if (categoria) {
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][field]=subcategoria`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][value]=${encodeURIComponent('%' + categoria + '%')}`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][condition_type]=like`);
  groupIdx++;
}

// Material (like)
const material = (input.material || '').trim();
if (material) {
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][field]=material`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][value]=${encodeURIComponent('%' + material + '%')}`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][condition_type]=like`);
  groupIdx++;
}

// Precio mínimo (gteq en sale_price)
const precioMin = (input.precio_minimo || '').trim();
if (precioMin) {
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][field]=sale_price`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][value]=${encodeURIComponent(precioMin)}`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][condition_type]=gteq`);
  groupIdx++;
}

// Precio máximo (lteq en sale_price)
const precioMax = (input.precio_maximo || '').trim();
if (precioMax) {
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][field]=sale_price`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][value]=${encodeURIComponent(precioMax)}`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][condition_type]=lteq`);
  groupIdx++;
}

const url = parts.length ? `${BASE}?${parts.join('&')}` : BASE;

return [{ json: { url } }];

// Formatea la respuesta del API para el agente
const data = $input.first().json;
const items = data.items || [];
const totalCount = data.total_count || 0;
const sc = data.search_criteria || {};

if (items.length === 0) {
  return [{ json: { resultado: 'No se encontraron productos con los criterios indicados.', total: 0, productos: [] } }];
}

const productos = items.map(p => ({
  product_id: p.product_id,
  sku: p.sku,
  nombre: p.name,
  marca: p.brand || '',
  precio_regular: p.regular_price || '',
  precio_venta: p.sale_price || '',
  stock: p.stock,
  subcategoria: p.subcategoria || '',
  descripcion_corta: p.short_description || '',
  imagen: p.imagen_principal || '',
  url_producto: p.product_id ? `https://194.195.92.107:444/productos/product/view/id/${p.product_id}` : (p.product_id ? `https://194.195.92.107:444/productos/product/view/id/${p.product_id}` : '')
}));

return [{ json: {
  total: totalCount,
  pagina_actual: sc.current_page || 1,
  resultados_en_pagina: items.length,
  productos
} }];

